WITH payload AS (SELECT $archive_payload$[{"id":"d12cf02e-c7bb-55fb-b93b-08d9c8584532","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -باغ كيدي تسبب يف السجن -مطالبة املدعي تعزير املدعى عليها -تقدمي با غ للجهة املختصة حق لكل من يتعرض ألذى -رد الدعوى.","document_number":"34308053","case_number":"34234911","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/29","year":"1434","subject":"إيذاء الغير (حق خاص) -باغ كيدي تسبب يف السجن -مطالبة املدعي تعزير املدعى عليها -تقدمي با غ للجهة املختصة حق لكل من يتعرض ألذى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/29 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34308053 :‬‬\n                         ‫َر ْق ُم الدعوى‪34234911 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34344572‬تاريخه‪1434/10/29 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬بــاغ كيــدي تســبب يف الســجن ‪ -‬مطالبــة‬\n      ‫املدعــي تعزيــر املدعــى عليهــا ‪ -‬تقــدمي بــا ٍغ للجهــة املختصــة حــق لــكل‬\n                                                 ‫مــن يتعــرض ألذى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                                ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليهــا قدمــت ضــده بالغــا ملركــز هيئــة‬\n      ‫األمــر باملعــروف والنهــي عــن املنكــر بغيــر حــق بعــد أن قامــت بتصويــره‬\n      ‫فقبــض عليــه وأوقــف ملــدة يــوم واحــد ومتــت إحالتــه إلــى جهــة التحقيــق‪،‬‬\n      ‫وطلــب احلكــم عليهــا بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أقــرت املدعــى عليهــا‬\n      ‫مبــا جــاء يف الدعــوى مــن بــاغ ضــد املدعــي بعــد تصويرهــا لــه ودفعــت‬\n      ‫بــأن ســبب ذلــك قيــام املدعــي بأخــذ جــوال ابنهــا واتصــل بهــا منــه كمــا‬\n      ‫أنــه قــام بالوقــوف أمــام الفنــدق الــذي تقيــم فيــه‪ -‬مــن حــق كل أحــد‬\n      ‫يتعــرض ألذى أن يتقــدم ببــاغ للجهــات الرســمية ومــا قامــت بــه املدعــى‬\n      ‫عليهــا ال يوجــب عقوبتهــا‪ -‬قضــت احملكمــة بــرد دعــوى املدعــي وأخلــت‬\n      ‫ســبيل املدعــى عليهــا‪ -‬قنعــت املدعــى عليهــا باحلكــم وعــارض عليــه‬\n\n\n‫‪343‬‬\n\f        ‫املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫اجلزائيــة‬\n   ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة األحســاء املكلــف برقــم ‪ 34234911‬وتاريــخ‬\n‫‪1434/05/21‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341242747‬وتاريــخ‬\n‫‪ 1434/05/21‬ه ـ ففــي يــوم األحــد املوافق‪1434/08/21‬ه ـ افتتحــت‬\n‫اجللســة األولــى الســاعة ‪09 : 00‬وفيهــا حضــر ‪ .....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .....‬وحضــرت حلضــوره املدعــى عليهــا‬\n‫‪ ......‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وحضــر برفقهــا‬\n‫املعــرف لهــا ابنهــا ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪.......‬‬\n‫وادعــى املدعــي قائــا يف دعــواه أنــه منــذ ثالثــة أشــهر كنــت يف املدينــة‬\n‫املنــورة وقامــت هــذه احلاضــرة بتصويــري وتقــدمي بــاغ ال اعــرف مضمونه‬\n‫ضــدي لــدى مركــز هيئــة األمــر باملعــروف والنهي عــن املنكر يف املدينة‬\n‫املنــورة واتصلــت بأهلــي وأخبرتهــم عــن تقــدمي الشــكوى ضــدي وهــددت‬\n‫بســجني وقبــض علــي مــن قبــل الهيئــة ملــدة يــوم واحــد وحقــق معــي لــدى‬\n‫هيئــة التحقيــق واالدعــاء العــام يف املدنيــة املنــورة مــن قبــل احملقــق ثــم‬\n‫أفــرج عنــي لــذا اطلــب إثبــات ذلــك ومعاقبــة املدعــى عليهــا حســب الوجــه‬\n‫الشــرعي هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليهــا أجابــت‬\n‫قائلــة مــا ذكــره املدعــي صحيــح فقــد تقدمــت ببــاغ ببــاغ ضــده لــدى‬\n‫هيئــة األمــر باملعــروف والنهــي عــن املنكــر باملدنيــة املنــورة لكونــه اخــذ‬\n‫جــوال ابنــي هــذا احلاضــر وصورتــه لكونــه واقــف لــدى الفنــدق الــذي‬\n\n                                                                                       ‫‪344‬‬\n\f      ‫أقيــم فيــه واتصــل بــي ابنــي وكلمنــي هــذا احلاضــر املدعــي بجــوال ابنــي‬\n      ‫وقــال لــي إننــي وصورتــه لــدى بــاب الفندق وقدمت البــاغ هكذا أجابت‬\n      ‫وبعرضــه علــى املدعــي قــرر قائــا كل مــا ذكرتــه املدعــى عليهــا غيــر‬\n      ‫صحيــح فلــم اكلمهــا بجــوال ابنهــا وأمــا حضــوري إلــى الفنــدق فقــد‬\n      ‫كنــت انتظــر زمالئــي لــي كانــوا يقيمــون يف الفنــدق نفســه وأطالــب‬\n      ‫بإيقــاف املدعــى عليهــا كمــا أوقفتنــي يف املدينــة هكــذا قــرر فبنــاء‬\n      ‫علــى مــا ســلف مــن الدعــوى واإلجابــة و إقــرار املدعــى عليهــا بتقــدمي‬\n      ‫بــاغ لــدى مركــز الهيئــة يف املدينــة املنــورة يتضمــن مــا ذكرتــه أعــاه‬\n      ‫ونظــرا ألنــه مــن حــق كل احــد يتعــرض ألذى أن يتقــدم ببــاغ للجهــات‬\n      ‫الرســمية وعلــى اجلهــات الرســمية اتخــاذ مــا يلــزم بشــأنه ونظــرا لكونــه‬\n      ‫لــم يصــدر مــن املدعــى عليهــا أي تعــدي علــى املدعــي بغيــر حــق وإمنــا‬\n      ‫تقدمــت ببالغهــا مطالبــة مبحاســبة مــن اعتــدى عليهــا حســب الوجــه‬\n      ‫الشــرعي ونظــرا لكــون هــذا العمــل الــذي قامــت بــه ال يوجــب عليهــا‬\n      ‫أي عقوبــة فقــد حكمــت بــرد الدعــوى وأخليــت ســبيل املدعــى عليهــا‬\n      ‫مــن هــذه املطالبــة وبــه حكمــت وبعرضــه علــى املدعــي واملدعــى عليهــا‬\n      ‫قــررت املدعــى عليهــا قناعتهــا بــه وقــرر املدعــي عــدم القناعــة وطلــب‬\n      ‫االســتئناف مكتفيــا مبــا ورد يف دعــواه عــن تقــدمي الئحــة اعتراضيــه‬\n      ‫فأجبتــه لطلبــه وقــررت بعــث املعاملــة إلــى محكمــة االســتئناف باملنطقة‬\n      ‫الشــرقية حســب التعليمــات وأقفلــت اجللســة الســاعة التاســعة والنصــف‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‬\n                                                          ‫حــرر يف ‪1434/8/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n\n\n‫‪345‬‬\n\f‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n‫برقــم ‪ 341242747‬وتاريــخ ‪1434/9/9‬ه املقيــدة لــدى احملكمــة برقــم‬\n‫‪ 34/2200730‬وتاريــخ ‪1434/9/16‬ه املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ).....(/‬املســجل برقــم ‪34308053‬‬\n‫وتاريــخ ‪1434/8/29‬ه اخلــاص بدعــوى‪ ).....( /‬ضــد‪ ).....( /‬يف قضيــة‬\n‫تهديــد الغيــر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                 ‫وصحبــه وســلم حــرر يف ‪1434/10/28‬هــ‪.‬‬\n\n\n\n\n                                                                                  ‫‪346‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":343,"source_page_end":346,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"61f9d0053029d0530ee1150194e50637c362af708fb9ac13b0fca2e82a680e41","normalized_text_hash":"c91f5b6e233343b0e4855635a948cf50701ccba14f08e0a14c15c8ba7d4a2462","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p343-34308053"},{"id":"93e10afe-b72a-5147-b3af-3722c8aeecd7","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب والتلفظ -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -تعذر الصلح بن الطرفن -عجز املدعي عن إقامة البينة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","document_number":"34264795","case_number":"34238271","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/10","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب والتلفظ -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -تعذر الصلح بن الطرفن -عجز املدعي عن إقامة البينة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/10 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34264795 :‬‬\n                         ‫َر ْق ُم الدعوى‪34238271 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34276627‬تاريخه‪1434/07/24 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص) ‪ -‬اعتــداء بالســب والتلفــظ ‪ -‬مطالبــة‬\n      ‫املدعــي باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬تعــذر الصلــح بــن‬\n      ‫الطرفــن ‪ -‬عجــز املدعــي عــن إقامــة البينــة ‪ -‬ميــن املدعــى عليــه علــى‬\n                                                     ‫نفــي الدعــوى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n                                       ‫‪ -1‬البينة على املدعي واليمني على من أنكر‪.‬‬\n                                                          ‫‪ -2‬األصل براءة الذمة‪.‬‬\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه تلفــظ عليــه بقولــه لــه ( يــا فاجــر)‬\n      ‫ودعــا عليــه باملــوت والــزوال‪ ،‬وطلــب احلكــم عليــه بعقوبــة تعزيريــة لقــاء‬\n      ‫ذلــك‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي جملــة وتفصيــا‪-‬‬\n      ‫طلبــت احملكمــة مــن املدعــي أن يقــدم بينتــه علــى دعــواه فقــرر أنــه ال‬\n      ‫بينــة لديــه وطلــب ميــن املدعــى عليــه علــى نفــي دعــواه فأداهــا طبــق مــا‬\n      ‫طلــب منــه‪ -‬قضــت احملكمــة بعــدم ثبــوت دعــوى املدعــي وأخلــت ســبيل‬\n      ‫املدعــى عليــه منهــا‪ -‬عــارض املدعــي علــى احلكــم‪ -‬قــررت محكمــة‬\n                                                 ‫االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n‫‪347‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n‫اجلزائيــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 34238271‬وتاريــخ‬\n‫‪1434/5/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341259373‬وتاريــخ‬\n‫‪1434/05/25‬ه ـ ففــي يــوم االثنــن املوافــق ‪1434/07/10‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10.00‬وفيهــا حضــر ‪ ....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .....‬وادعــى علــى احلاضــر معــه يف مجلــس احلكــم‬\n‫‪ ......‬ســعودي بالســجل املدنــي رقــم ‪ .......‬قائــا يف حتريــر دعــواه إنــه يــوم‬\n‫اخلميــس املوافــق ‪1434/5/2‬ه ـ وقــع بينــي وبــن املدعــى عليــه خــاف‬\n‫حــول نشــوز زوجتــي وذهابهــا إلــى منزلــي والدهــا املدعــى عليــه عندهــا‬\n‫تلفــظ علــي فقــال لــي واهلل العظيــم إنــك فاجــر ثــم دعــا علــي باملــوت‬\n‫والــزوال كــرر ذلــك فأطلــب تأديبــه علــى تلفظــه علــي ســبا ودعــاء هــذه‬\n‫دعــواي وبســؤال املدعــى عليــه عمــا جــاء بدعــوى املدعــي أجــاب قائــا‬\n‫لقــد زوجــت املدعــي ابنتــي منــذ ثــاث ســنوات وأجنبــت لــه أوالد ووقــع‬\n‫بينهمــا خــاف وابنتــي يف منزلــي حاليــا وتقدمــت بدعــوى إلــى احملكمــة‬\n‫العامــة باملدينــة املنــورة تطالــب بالنفقــة واحلضانــة ألوالدهــا وســوف تقــدم‬\n‫دعــوى بفســخ النــكاح ومــا ذكــره املدعــي مــن أنــي دعــوت عليــه باملــوت‬\n‫والــزوال وأنــي قلــت لــه يــا فاجــر فهــذا غيــر صحيــح هكــذا أجــاب‬\n‫هــذا وقــد جــرى الكتابــة إلــى قســم الصلــح باحملكمــة باخلطــاب رقــم‬\n‫‪ 341259373‬يف ‪1434/6/17‬ه ـ حملاولــة الصلــح بني املتداعيني فوردت‬\n‫اإلفــادة باخلطــاب رقــم ‪ 341259373‬يف ‪1434/6/26‬ه ـ واملتضمــن‬\n\n                                                                                        ‫‪348‬‬\n\f      ‫امتنــاع املدعــي مــن قبــول الصلــح ويف أثنــاء اجللســة ذكــرت املتداعيــن‬\n      ‫مبــا بينهمــا مــن صلــة ورحــم ولعلهمــا يدخــان بينهمــا مــن يســعى بالصلــح‬\n      ‫بينهمــا فلــم يقبــا ذلــك وأصــر املدعــي علــى دعــواه وبعــرض جــواب‬\n      ‫املدعــى عليــه علــى املدعــي رد قائــا الصحيــح مــا ذكرتــه يف دعــواي‬\n      ‫وال بينــة لــي علــى دعــواي وأطلــب حتليــف املدعــى عليــه علــى نفــي دعــواي‬\n      ‫وبعرضــه علــى املدعــى عليــه رد قائــا ال مانــع لــدي مــن بــذل اليمــن‬\n      ‫فــأذن لهــا ببذلــه فحلــف قائــا ‪ :‬واهلل الــذي ال إلــه غيــره عالــم الغيــب‬\n      ‫والشــهادة يعلــم خائنــة األعــن ومــا تخفــي الصــدور أنــي لــم أقــل للمدعــي‬\n      ‫هــذا احلاضــر يــا فاجــر ولــم أدعــو عليــه باملــوت والــزوال وأن دعــواه هــذه‬\n      ‫غيــر صحيحــه هكــذا حلــف وقبــل املدعــي ميينــه علــى الصفــة املذكــورة‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه أنكــر‬\n                                                                                    ‫فبنـ ً‬\n      ‫دعــوى املدعــي وقــرر املدعــي بأنــه ال بينــة لــه علــى دعــواه وطلــب حتليــف‬\n      ‫املدعــى عليــه علــى نفــي دعــواه ومبــا أن املدعــى عليــه بــذل اليمــن علــى‬\n      ‫الصفــة التــي طلبهــا املدعــي ومبــا أن مــن املقــرر أن البينــة علــى املدعــي‬\n      ‫واليمــن علــى مــن أنكــر ألن األصــل بــراءة الذمــة جلميــع مــا ذكــر فقــد‬\n      ‫حكمــت بعــدم ثبــوت دعــوى املدعــي وأخليــت ســبيل املدعــى عليــه مــن‬\n      ‫هــذه الدعــوى وبعرضــه قــرر املدعــي عــدم قناعتــه باحلكــم وطلــب رفعــه‬\n      ‫إلــى محكمــة االســتئناف بــدون الئحــة اعتراضيــة فأجيــب لطلبــه ‪،‬‬\n      ‫وقــد انتهــت اجللســة يف متــام الســاعة ‪ 10.30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/10‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضاة االســتئناف بالدائــرة اجلزائية السادســة مبحكمة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا اإلطــاع علــى املعاملــة‬\n\n\n‫‪349‬‬\n\f‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم‬\n‫(‪ )341259373‬وتاريــخ ‪1434/7/12‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة الشــيخ‪ ).....(/‬القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة‬\n‫برقــم ‪ 34264795‬وتاريــخ ‪1434/7/10‬ه املتضمــن دعــوى (‪ ).....‬ضــد‪/‬‬\n‫(‪ ).....‬ســعوديي اجلنســية يف ســب وشــتم‪ ،‬احملكــوم فيــه مبــا دون باطنــه‬\n‫وبدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم‪ ،‬واهلل‬\n         ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                   ‫‪350‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":347,"source_page_end":350,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"546fe4b3b680e366f87bfd6ffe722470b49a4d25f9a077125c3cb49ea92e6502","normalized_text_hash":"a2d145857019e392178b8341a097fcb6fb8ab154f9fd0a74dd7ee56049492658","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p347-34264795"},{"id":"485bb741-576a-5df8-80bc-da0b08468586","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب والشتم -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -افتقاد املدعي البينة -مين املدعى عليه على نفي الدعوى -رد الدعوى .","document_number":"34288000","case_number":"34271087","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف 351 املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/3","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب والشتم -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -افتقاد املدعي البينة -مين املدعى عليه على نفي الدعوى -رد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/8/3 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34288000 :‬‬\n                         ‫َر ْق ُم الدعوى‪34271087 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34302005‬تاريخه‪1434/08/22 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالســب والشــتم‪ -‬مطالبــة املدعــي‬\n      ‫باملجــازاة‪ -‬إنــكار املدعــى عليــه الدعــوى‪ -‬افتقــاد املدعــي البينــة‪ -‬ميــن‬\n                               ‫املدعــى عليــه علــى نفــي الدعــوى‪ -‬رد الدعــوى ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬لــو يعطــى النــاس بدعواهــم‬\n      ‫الدعــى أقــوام دمــاء رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه)‪.‬‬\n      ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                                                 ‫علــى مــن أنكــر)‪.‬‬\n                                                         ‫‪ -3‬األصل براءة الذمة‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بســبه وشــتمه مبــا هــو مذكــور يف‬\n      ‫دعــواه‪ ،‬وطلــب احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعى‬\n      ‫عليــه مــا جــاء يف دعــوى املدعــي جملــة وتفصيــا‪ -‬طلبــت احملكمــة مــن‬\n      ‫املدعــي أن يقــدم بينتــه علــى دعــواه فقــرر أنــه ال بينــة لديــه وطلــب ميــن‬\n      ‫املدعــى عليــه علــى نفــي دعــواه فأداهــا طبــق مــا طلــب منــه‪ -‬قضــت‬\n      ‫احملكمــة بعــدم ثبــوت دعــوى املدعــي وأخلــت ســبيل املدعــى عليــه‬\n      ‫منهــا‪ -‬عــارض املدعــي علــى احلكــم‪ -‬قــررت محكمــة االســتئناف‬\n\n‫‪351‬‬\n\f                                                        ‫املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫باملدينة املنورة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 34271087‬وتاريــخ ‪1434/6/13‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341425841‬وتاريــخ ‪1434/06/13‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافــق ‪1434/08/03‬ه ـ افتتحــت اجللســة الســاعة ‪08 :45‬‬\n‫وفيهــا حضــر ‪ .....‬ســوري اجلنســية مبوجــب رخصــة اإلقامــة الصــادرة مــن‬\n‫جــوازات املدينــة املنــورة رقــم ‪ .....‬وادعــى علــى احلاضــر معــه يف مجلــس‬\n‫احلكــم ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬قائــا يف‬\n‫حتريــر دعواهــا إنــه يف تاريــخ ‪1434/4/24‬ه ـ قــام املدعــى عليــه بالتلفظ‬\n‫علــي أمــام ســكنه والــذي يقــع علــى امتــداد طريــق األميــر عبــد املجيــد‬\n‫بجــوار مستشــفى الــوالدة باملدينــة املنــورة بقولــه بنتــك ســأفعل بهــا وأنــت‬\n‫ســوف ‪ ....‬وحــاول التهجــم علــي بضربــي إال إننــي ركبــت الســيارة‬\n‫وذهبــت لــذا أطلــب احلكــم بتأديــب املدعــى عليــه حيــال تلفظــه علــي‬\n‫وحملاولــة اعتــداءه علــي هــذه دعــواي وبســؤال املدعــى عليــه عمــا جــاء‬\n‫بدعــوى املدعــي أجــاب قائــا مــا ذكــره املدعــي يف دعــواه غيــر صحيــح‬\n‫فلــم أتلفــظ عليــه ولــم أتهجــم أو أضربــه هكــذا أجــاب وبعرضــه علــى‬\n‫املدعــي رد قائــا الصحيــح مــا ذكــرت يف دعــواي وال بينــة لــي علــى‬\n‫دعــواي وأطلــب حتليــف املدعــى عليــه علــى نفــي دعــواي وبعرضــه علــى‬\n‫املدعــى عليــه رد قائــا ال مانــع لــدي مــن بــذل اليمــن فــأذن لــه ببذلــه‬\n‫فحلــف قائــا (واهلل الــذي ال إلــه غيــره عالــم الغيــب والشــهادة يعلم خائنة‬\n\n                                                                                      ‫‪352‬‬\n\f      ‫األعــن ومــا تخفــي الصــدور أنــي لــم أتلفــظ علــى املدعــي هــذا احلاضــر‬\n      ‫وتــد ولــم أقــل ســأفعل ببنتــك ولــم أقــل لــه ســوف ‪ ....‬ولــم أحــاول التهجــم‬\n      ‫عليــه بضربــه وواهلل أن دعــواه هــذه غيــر صحيحــة) هكــذا حلــف وقبــل‬\n      ‫املدعــي ميــن املدعــى عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫ومبــا أن املدعــى عليــه أنكــر دعــوى املدعــي وقــرر املدعــي بأنــه ال بينــة‬\n      ‫لــه علــى دعــواه وطلــب حتليــف املدعــى عليــه علــى نفــي دعــواه ومبــا أن‬\n      ‫املدعــى عليــه بــذل اليمــن علــى الصفــة التــي طلبهــا املدعــي ومبــا أن مــن‬\n      ‫املقــرر أن البينــة علــى املدعــي واليمــن علــى مــن أنكــر لعمــوم قولــه‬\n      ‫صلــى اهلل عليــه وســلم (ولــو يعطــى النــاس بدعواهــم الدعــى أقــوام دمــاء‬\n      ‫رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه) وألن األصــل بــراءة‬\n      ‫الذمــة جلميــع مــا ذكــر فقــد حكمــت بعــدم ثبــوت دعــوى املدعــي و‬\n      ‫أخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى وبعرضــه قــرر املدعــي‬\n      ‫عــدم قناعتــه باحلكــم وطلــب رفعــه إلــى محكمــة االســتئناف بــدون‬\n      ‫الئحــة اعتراضيــه فأجيــب لطلبــه وقــد انتهــت اجللســة يف متــام الســاعة‬\n      ‫‪ 09.15‬وبــاهلل التوفيــق‪ ،،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                           ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/8/3‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة اإلســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 341425841‬وتاريــخ‬\n      ‫‪1434/8/7‬ه ـ املرفــق بهــا القــرار رقــم ‪ 34288000‬وتاريــخ ‪1434/8/3‬ه‬\n      ‫الصــادر مــن فضيلــة الشــيخ د‪ ................../‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫باملدينــة املنــورة املتضمــن دعــوى املدعــي‪ ................./‬ســوري اجلنســية‬\n\n\n‫‪353‬‬\n\f‫ضــد‪ ................./‬ســعودي اجلنســية املتهــم يف إيــذاء الغيــر‪ ،‬احملكــوم‬\n‫فيــه مبــا دون بباطنــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه قررنــا املوافقــة‬\n‫علــى احلكــم‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                            ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪354‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":351,"source_page_end":354,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"77166b7be876ec28edd31393f9738a932fc930b183aac8b7a2123913bd105510","normalized_text_hash":"745017017dc90c6e0dea371e601a86330fc55ce8e737ff367b1dc1bdd6f7829a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p351-34288000"},{"id":"8cdcea15-f374-532e-a959-e16fa3978131","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالسب والتلفظ يف مكان عام - مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -تعذر الصلح بن الطرفن -بينة املدعي غير موصلة -رد الدعوى -إفهام املدعي بأن له حق طلب بن املدعى عليه.","document_number":"34335558","case_number":"34279807","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/20","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالسب والتلفظ يف مكان عام - مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -تعذر الصلح بن الطرفن -بينة املدعي غير موصلة -رد الدعوى -إفهام املدعي بأن له حق طلب بن املدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/10/20 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34335558 :‬‬\n                          ‫َر ْق ُم الدعوى‪34279807 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34367356‬تاريخه‪1434/11/24 :‬هـ‬\n\n\n       ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالســب والتلفــظ يف مــكان عــام ‪-‬‬\n       ‫مطالبــة املدعــي باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬تعــذر الصلــح‬\n       ‫بــن الطرفــن ‪ -‬بينــة املدعــي غيــر موصلــة ‪ -‬رد الدعــوى ‪ -‬إفهــام املدعــي‬\n                                             ‫بــأن لــه حــق طلــب بــن املدعــى عليــه‪.‬‬\n\n\n\n\n       ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                                ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n       ‫ادعــى املدعــي بــأن املدعــى عليــه ســبه واتهمــه بالســكر أمــام جمــع مــن‬\n       ‫النــاس يف دائــرة حكوميــة‪ ،‬وطلــب احلكــم عليــه بعقوبــة تعزيريــة لقــاء‬\n       ‫ذلــك‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي جملــة وتفصيــا‬\n       ‫تعــذر إجــراء الصلــح بــن الطرفــن طلبــت احملكمــة مــن املدعــي أن‬\n       ‫يقــدم بينتــه علــى دعــواه فأحضــر شــاهد ًا واحــد ًا فقــط‪ ،‬ومــؤدى ذلــك‬\n       ‫أن بينتــه غيــر موصلــة إلثبــات دعــواه‪ -‬مت إفهــام املدعــى أن لــه حــق طلــب‬\n       ‫اليمــن مــن املدعــى عليــه ‪ -‬قضــت احملكمــة بعــدم ثبــوت دعــوى املدعــي‬\n       ‫وصرفــت النظــر عنهــا‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه‬\n                   ‫املدعــي‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n‫‪355‬‬\n\f‫احلمــد اهلل وحــده وبعــد فلــدي انــا (‪ ).....‬القاضــي باحملكمــة اجلزائيــة‬\n‫باملدينة املنورة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 34279807‬وتاريــخ ‪1434/06/17‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341471143‬وتاريــخ ‪1434/6/17‬ه ـ ففــي‬\n‫يــوم االثنــن املوافــق ‪1434/7/3‬ه ـ افتتحــت اجللســة الســاعة ‪10: 00‬‬\n‫صباحــا وفيهــا حضــر ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ....‬وادعــى علــى احلاضــر معــه باملجلــس الشــرعي ‪ .....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ....‬قائــا يف حتريــر دعــواه إن املدعــى‬\n‫عليــه منــذ أســبوعني تقريبــا ســبني واتهمنــي وقذفنــي بالســكر يف إدارة‬\n‫املــرور أمــام جمــع مــن النــاس فأطلــب ســؤاله وتأديبــه عمــا تلفــظ بــه علــي‬\n‫هــذه دعــواي وبســؤال املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي ال‬\n‫صحــة لــه ودعــواه هــذه ابتــزاز إلرغامــي للتنــازل عــن دعــواي حيــث إن‬\n‫املدعــي قــام بصدمــي وعائلتــي بســيارته وتســبب لنــا يف أضــرار بدنيــة‬\n‫ونفســية وقــد حضــر رجــال املــرور وقــرروا نســبة اخلطــأ عليــه ‪ %75‬وعلــي‬\n‫‪ %25‬وقــد اعترضــت علــى هــذه النســبة نظــرا لكونــه هــو املخطــئ وال‬\n‫ميلــك رخصــة قيــادة هكــذا أجــاب وبســؤال املدعــي عــن البينــة فقــال‬\n‫لــدي بينــة شــهود ويف جلســة أخــرى وفيهــا حضــر املدعــي كمــا حضــر‬\n‫املدعــى عليــه وبســؤال املدعــي عــن بينــة الشــهود أحضــر للشــهادة (‪).....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم(‪ ).....‬وبســؤاله عــن مــا‬\n‫لديــه مــن شــهادة قــال أشــهد انــه يف شــهر رجــب املاضــي وعندمــا كنــت‬\n‫مــع أخــي يف إدارة املــرور باملدينــة املنــورة تلفــظ املدعــى عليــه علــى‬\n\n                                                                                       ‫‪356‬‬\n\f      ‫أخــي بقولــه انــه حضــر ســكرانا وريقــه واصــل هكــذا شــهد وبعــرض‬\n      ‫الشــاهد وشــهادته علــى املدعــى عليــه أجــاب قائــا مــا ذكــره الشــاهد ال‬\n      ‫صحــة لــه فطلبــت مــن املدعــي زيــادة بينــة فقــال نعــم لــدي شــاهد آخــر لــم‬\n      ‫يســتطع احلضــور اليــوم وأطلــب مهلــة حلضــوره ورفعــت اجللســة الــى ذلــك‬\n      ‫وحملاولــة الصلــح بينهــم ويف جلســة اخــرى وفيهــا حضــر املدعــي (‪).....‬‬\n      ‫كمــا حضــر املدعــى عليــه وبســؤال املدعــي عــن زيــادة البينــة فقــال ان‬\n      ‫الشــاهد ايضــا لــم يحضــر هــذا اليــوم فجــرى عــرض الصلــح بينهمــا ولــم‬\n      ‫يصطلحــا فبنــاء علــى مــا تقــدم وحيــث لــم يحضــر املدعــي بينــة موصلــة‬\n      ‫علــى دعــواه وحيــث ان الدعــوى دعــوى جزائيــة فقــد أفهمــت املدعــي أن‬\n      ‫لــه حــق طلــب اليمــن مــن املدعــى عليــه فقــال ال نطلــب منــه اليمــن وال‬\n      ‫نقبلهــا منــه فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة ونظــرا إلنــكار‬\n      ‫املدعــى عليــه الدعــوى ولــم يحضــر بينــة موصلــة علــى دعــواه ولــم يرد ميني‬\n      ‫خصمــه فبنــاء عليــه لــم تثبــت لــدي صحــة الدعــوى وحكمــت بصــرف‬\n      ‫النظــر عــن دعــوى املدعــي جتــاه املدعــى عليــه وبعــرض احلكــم علــى‬\n      ‫الطرفــن قــرر املدعــي عــدم القناعــة واســتعد بتقــدمي الئحــة اعتراضيــة‬\n      ‫وأمــا املدعــى عليــه فقــرر القناعــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/10/20‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪341471143‬‬\n      ‫وتاريــخ ‪1434/11/6‬ه ـ املرفــق بهــا الصــك الشــرعي رقــم ‪34335558‬‬\n      ‫وتاريــخ ‪1434/10/20‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ).....(/‬القاضــي‬\n\n\n‫‪357‬‬\n\f‫يف احملكمــة اجلزائيــة باملدينــة املنــورة‪ ،‬املتضمــن دعــوى (‪ ).....‬ضــد‪/‬‬\n‫(‪ ).....‬املتهــم بقضيــة قــذف وشــتم وســب احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه قررنــا املوافقــة علــى احلكــم واهلل‬\n     ‫املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                 ‫‪358‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":355,"source_page_end":358,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"041ad18fd386d05c09ab53ff0097ab9fcc17a5682f03b5a7fa69a9780e0b40ef","normalized_text_hash":"60f482544eabe685af866c538b9d1cb7c2e60197655b408306e177ef16cac5a2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p355-34335558"},{"id":"79941f69-2589-5fd9-84d7-92f16b7727a7","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالقذف والسب والشتم -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","document_number":"34359926","case_number":"34300095","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/13","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالقذف والسب والشتم -مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -مين املدعى عليه على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/11/13 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34359926 :‬‬\n                          ‫َر ْق ُم الدعوى‪34300095 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34382932‬تاريخه‪1434/12/22 :‬هـ‬\n\n\n       ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالقــذف والســب والشــتم ‪ -‬مطالبــة‬\n       ‫املدعــي باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬بينــة املدعــي غيــر‬\n              ‫موصلــة ‪ -‬ميــن املدعــى عليــه علــى نفــي الدعــوى‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n       ‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                                         ‫مــن أنكــر)‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بقذفــه كمــا ســبه وشــتمه مبــا‬\n       ‫هــو مذكــور يف دعــواه‪ ،‬وطلــب احلكــم عليــه بحــد القــذف وعقوبــة‬\n       ‫تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي‬\n       ‫جملــة وتفصيــا‪ -‬طلبــت احملكمــة مــن املدعــي أن يقــدم بينتــه علــى‬\n       ‫دعــواه فأحضــر شــاهد ًا واحــد ًا فقــط‪ ،‬ومــؤدى ذلــك أن بينتــه غيــر‬\n       ‫موصلــة إلثبــات دعــواه‪ -‬طلــب املدعــي ميــن املدعــى عليــه علــى نفــي‬\n       ‫دعــواه فأداهــا طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بصــرف النظــر‬\n       ‫عــن دعــوى املدعــي‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي‪-‬‬\n                           ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n‫‪359‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34300095‬وتاريــخ‬\n‫‪1434/06/28‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341574788‬وتاريــخ‬\n‫‪1434/6/28‬ه ـ ففــي يــوم االثنــن املوافــق ‪1434/07/24‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 02 : 30‬وفيها حضر املدعي(‪ ).....‬باكســتاني اجلنســية‬\n‫مبوجــب رخصــة اإلقامــة رقــم(‪ ).....‬وحضــر حلضــوره املدعــى عليــه (‪).....‬‬\n‫باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم(‪ ).....‬وادعــى املدعــي‬\n‫ا وهــو يتحــدث اللغــة احملليــة إن املدعــى عليــه حضــر عنــد بيتي وقال‬       ‫قائـ ً‬\n‫أنتــم أهــل اللحــى مجرمــن ونصابــن ودجالــن ومنافقــن ثــم هددنــي‬\n‫باغتيالــي وتلفــظ علــي بألفــاظ بذيئــة جــد ًا بــا مبــاالة حيــث قــال يــا ولــد‬\n‫الكلــب يــا ولــد الزنــا يــا خنزيــر لــذا أطلــب احلكــم عليــه بحــد القــذف‬\n‫وعقوبــة تعزيريــه هــذه دعــواي وبعــرض دعــوى املدعــي علــى املدعــى‬\n‫ا وهــو يتحــدث اللغــة احملليــة مــا ذكــره املدعــي يف‬   ‫عليــه أجــاب قائ ـ ً‬\n‫دعــواه غيــر صحيــح هــذه إجابتــي وبســؤال املدعــي هــل لديــك بينــه فقــال‬\n‫نعــم وأطلــب مهلــه إلحضارهــا هكــذا أفــاد وعليــه أجبــت طلبــه ورفعــت‬\n‫اجللســة لذلك ويف يوم الثالثاء املوافق‪1434/08/ 23‬هـ افتتحت اجللســة‬\n‫الســاعة وفيهــا حضــر املدعــي واملدعــى عليــه وبســؤال املدعــي عمــا وعــد‬\n‫بــه يف اجللســة املاضيــة أحضــر للشــهادة وأدائهــا اجلنســية مبوجــب الهويــة‬\n‫اخلاصــة للبرماويــن رقــم ويبلــغ مــن العمــر خمســة وثالثــن ســنة وجــار‬\n‫ا (أشــهد هلل تعالــى‬ ‫للمدعــي وبســؤاله عمــا لديــه مــن شــهادة شــهد قائـ ً‬\n\n                                                                                          ‫‪360‬‬\n\f      ‫بانــي ســمعت وشــاهدت يقــول يــا أبــن الكلــب أنــت أبــن زنــا وحــاول‬\n      ‫ضربــه ولكنــه لــم يضربــه هــذه شــهادتي وبعــرض الشــاهد وشــهادته‬\n      ‫علــى املدعــى عليــه قــال أمــا الشــاهد فــا أعرفــه أمــا الشــهادة فغيــر‬\n      ‫صحيحــه هكــذا أجــاب وبســؤال املدعــي هــل لديــك زيــادة بينــه فقــال‬\n      ‫نعــم واطلــب مهلــة إلحضارهــا هكــذا أجــاب وأجبــت لطلبــه رفعــت‬\n      ‫اجللســة ويف يــوم اخلميــس املوافــق ‪1434/10/29‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة وفيهــا حضــر املدعــي واملدعــى عليــه وبســؤال املدعــي عمــا وعــد‬\n      ‫بــه يف اجللســة املاضيــة فأجــاب قائــا إن الشــاهد رفــض احلضــور وأطلــب‬\n      ‫ميــن املدعــى عليــه علــى نفــي دعــواي هكــذا أجــاب وبعــرض ذلــك علــى‬\n      ‫ا بعــد‬ ‫ا أنــا مســتعد ببــذل اليمــن فحلــف قائـ ً‬  ‫املدعــى عليــه أجــاب قائـ ً‬\n      ‫إذنــي لــه وتخويفــه مبــآالت اليمــن الكاذبــة واهلل الــذي ال الــه اال هــو‬\n      ‫الــذي يعلــم الســر وأخفــى أننــي لــم أقــل أنتــم يــا أهــل احلــي مجرمــن‬\n      ‫ونصابــن ودجالــن ومنافقــن يــا ولــد الكلــب يــا ولــد الزنــا يــا خنزيــر‬\n      ‫ولــم أهــدده باالغتيــال هكــذا حلــف فبنــاء علــى مــا ســلف مــن الدعــوى‬\n      ‫واإلجابــة وبعــد االطــاع علــى أوراق املعاملــة وإلنــكار املدعــى عليــه مــا‬\n      ‫نســب اليــه يف دعــوى املدعــي ولعــدم تقــدمي املدعــي بينــة موصلــة علــى‬\n      ‫دعــواه ولطلبــه ميــن املدعــى عليــه علــى نفــي دعــواه وحللــف املدعــى عليــه‬\n      ‫علــى ذلــك ولقولــه صلــى اهلل عليــه وســلم( البينــة علــى املدعــي واليمــن‬\n      ‫علــى مــن أنكــر ) ملــا ســبق كلــه فقــد صرفــت النظــر عــن دعــوى املدعي‬\n      ‫وبعــرض ذلــك علــى املدعــي قــرر االعتــراض بــدون الئحــة واملدعــى عليــه‬\n      ‫قــررا القناعــة بــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                  ‫آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n\n\n‫‪361‬‬\n\f‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة إلينــا شــفع‬\n‫خطــاب فضيلــة الرئيــس املســاعد باحملكمــة اجلزائيــة مبكــة املكرمــة‬\n‫رقــم ‪ 341574788‬وتاريــخ ‪1434/11/25‬ه ـ املشــتملة علــى القــرار‬\n‫الصــادر مــن فضيلــة الشــيخ‪ ).....( /‬القاضــي باحملكمــة اجلزائية مبكة‬\n‫املكرمــة املــؤرخ يف ‪1434/11/13‬ه ـ واملســجل بعــدد ‪، 34359926‬‬\n‫املتضمــن دعــوى ‪).....( /‬ضــد‪ ).....( /‬يف قضيــة ســب وشــتم احملكــوم‬\n‫فيــه مبــا ّدون بباطــن القــرار وبدراســة القــرار وصــورة ضبطــه تقــررت‬\n‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                          ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                  ‫‪362‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":359,"source_page_end":362,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ddf48559239a554cbc877cdd8f6cf9993e596ec6543eddb9f27fe70bfacd4fc8","normalized_text_hash":"736b96d05823d512b80a4f7b945ba358a27e8814f6a745a0fc13fd0e022ce271","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p359-34359926"},{"id":"98e6c63e-98e7-5909-a252-b8911d16c549","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالقذف والسب والشتم يف مكان عام -مطالبة املدعى باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -صرف النظر عن املطالبة بحد القذف -إدانة","document_number":"34283087","case_number":"34325005","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة الرس","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/30","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالقذف والسب والشتم يف مكان عام -مطالبة املدعى باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -صرف النظر عن املطالبة بحد القذف -إدانة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/30 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34283087 :‬‬\n                         ‫َر ْق ُم الدعوى‪34325005 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34323110‬تاريخه‪1434/9/21:‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالقــذف والســب والشــتم يف مــكان‬\n      ‫عــام ‪ -‬مطالبــة املدعــى باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬بينــة‬\n      ‫املدعــي غيــر موصلــة ‪ -‬صــرف النظــر عــن املطالبــة بحــد القــذف‪ -‬إدانــة‬\n                                                                    ‫بالســب والشــتم‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬كل املســلم علــى املســلم حــرام‬\n                                                            ‫دمــه ومالــه وعرضــه)‪.‬‬\n                                    ‫‪ -2‬املادة (‪ )17‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بقذفــه كمــا قــام بســبه وشــتمه‬\n      ‫وذلــك يف الدائــرة احلكوميــة التــي يعمــان بهــا‪ ،‬وطلــب احلكــم عليــه‬\n      ‫بحــد القــذف لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي‬\n      ‫جملــة وتفصيــا‪ -‬طلبــت احملكمــة مــن املدعــي أن يقــدم بينتــه علــى‬\n      ‫دعــواه فأحضــر شــاهدين شــهد أحدهمــا بصــدور مــا يوجــب حــد القــذف‬\n      ‫بحــق املدعــى عليــه منــه وأمــا الشــاهد اآلخــر فشــاهدته غيــر موصلــة‬\n      ‫إلثبــات موجــب حــد القــذف ومؤداهــا إثبــات مــا يوجــب التعزيــر‪ -‬قضــت‬\n      ‫احملكمــة بصــرف النظــر عــن مطالبــة املدعــي بحــد القــذف وقضــت‬\n\n‫‪363‬‬\n\f‫بإدانــة املدعــى عليــه بســب املدعــي والتلفــظ عليــه بألفــاظ نابيــة وقــررت‬\n‫جلــده خمســن جلــدة بحضــور املدعــي إن رغــب‪ -‬قنــع املدعــي باحلكــم‬\n‫وعــارض عليــه املدعــى عليــه‪ -‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                ‫علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ....‬رئيــس احملكمــة العامــة مبحافظــة‬\n‫الــرس وبنــاء علــى املعاملــة املقيــدة بــوارد احملكمــة برقــم ‪341697437‬‬\n‫يف ‪1434/07/15‬ه ـ واخلاصــة بدعــوى ضــد بشــأن ســب وقــذف عليــه يف‬\n‫هــذا اليــوم األحــد املوافــق ‪1434/07/23‬ه ـ الســاعة التاســعة افتتحــت‬\n‫اجللســة وحضــر ‪ ....‬ســجل مدنــي رقــم ‪ ....‬بصفتــه مدعيـ ًا وحضــر حلضــوره‬\n‫‪ ........‬ســجل مدني رقم ‪ ....‬بصفته مدعى عليه وادعى األول على الثاني‬\n‫ا أنــه يف يــوم االثنــن املوافــق ‪1434/06/26‬ه ـ وأثنــاء تأديــة عملــي‬  ‫قائـ ً‬\n‫يف محافظــة الــرس ويف وقــت الــدوام الرســمي قــام هــذا احلاضــر معــي‬\n‫بالتلفــظ علــي بألفــاظ قبيحــة وســبني وشــتمني وقذفنــي وقــال لــي يــا‬\n‫كلــب يــا خنيــث أمــام جميــع املوظفــن وأطلــب إقامــة حــد القــذف عليــه‬\n‫ومجازاتــه لقــاء هــذا الفعــل هكــذا ادعــى ولــدى ســؤال املدعــى عليــه‬\n‫ا إن جميــع مــا ذكــره املدعــي ضــدي غيــر صحيــح ويكــرم‬        ‫أجــاب قائـ ً‬\n‫هــو عــن هــذه األلفــاظ وال ميكــن أن يخــرج منــي هــذه األلفــاظ أبــد ًا وال‬\n‫أعتــرف بأنــه صــدر منــي شــيء مــن ذلــك هكــذا أجــاب وبعــد ســماع‬\n‫الدعــوى واإلجابــة وحيــث أنكــر املدعــى عليــه هــذه الدعــوى لــذا فقــد‬\n‫ســألت املدعــي هــل لديــك بينــة علــى صحــة دعــواك فأجاب نعم لــدي بينة‬\n‫وهــم الشــهود الذيــن ســمعوا منــه هــذه العبــارات والســب والشــتم أطلــب‬\n\n                                                                                    ‫‪364‬‬\n\f      ‫ســماع شــهادتهم ثــم أحضــر للشــهادة وأدائهــا كال مــن ‪ ....‬ســجل مدنــي‬\n      ‫رقــم ‪ ....‬و‪ .....‬ســجل مدنــي رقــم ‪ ....‬ولــدي ســؤال الشــاهدين عمــا لديهمــا‬\n      ‫ا أشــهد بــاهلل أنــه يف يــوم االثنــن‬\n                                             ‫مــن شــهادة أجــاب الشــاهد األول قائـ ً‬\n      ‫املوافــق ‪1434/06/26‬ه ـ ســمعت املدعــى عليــه يتكلــم بــكالم كثيــر‬\n      ‫بحــق املدعــي ويســبه ويشــتمه ومــن ضمــن مــا قــال هالكلــب عســاه ميــوت‬\n      ‫بســرطانه ولــم أســمع عبــارة يــا خنيــث هــذا مــا لــدي مــن شــهادة كمــا‬\n      ‫ا أشــهد بــاهلل أننــي ســمعت املدعــى عليــه‬   ‫أجــاب الشــاهد الثانــي قائ ـ ً‬\n      ‫يقــول عــن املدعــي هــذا خنيــث ويشــير بأصبعــه إشــارة قــذرة تعنــي أن‬\n      ‫املشــار إليــه أعزكــم اهلل خنيــث وســمعته يقــول يــا كلــب هــذا مــا لــدي‬\n      ‫مــن شــهادة وبعــد ســماع شــهادة الشــاهدين عرضنــا الشــهادة والشــهود‬\n      ‫علــى املدعــى عليــه فأجــاب أن الشــهادة غيــر صحيحــة وأمــا الشــهود فــإن‬\n      ‫الشــاهد األول ال أقــدح يف دينــه وال أمانتــه ولكــن بينــي وبينــه عــداوة‬\n      ‫وبينــي وبينــه مشــاكل يف العمــل وكذلــك الشــاهد الثانــي ال أقــدح يف‬\n      ‫دينــه وال أمانتــه ولكــن بينــي وبينــه عــداوة ومشــاكل يف العمــل هكــذا‬\n      ‫ـاء علــى املــادة الســابعة عشــرة مــن نظــام اإلجــراءات اجلزائيــة‬\n                                                                          ‫أجــاب وبنـ ً‬\n      ‫فقــد مت تبليــغ املدعــي العــام بدائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n      ‫ا أن هــذه‬  ‫الــرس بهــذه الدعــوى وقــد حضــر هــذه اجللســة وقــرر قائ ـ ً‬\n      ‫دعــوى حــق خــاص وال أدعــي بشــيء ضــد املدعــى عليــه يف الوقــت احلالــي‬\n      ‫وحيــث ادعــى املدعــى عليــه أن بينــه وبــن الشــاهدين عــداوة لــذا فقــد‬\n      ‫طلبــت منــه إثبــات ذلــك فطلــب إمهالــه إلــى يــوم األحــد القــادم املوافــق‬\n      ‫‪1434/07/30‬ه ـ ورفعــت اجللســة إلــى ذلــك اليــوم وعلــى مــا تقــدم جــرى‬\n      ‫التوقيــع مــن اجلميــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                     ‫آلــه وصحبــه وســلم حــرر يف ‪1434/07/23‬هــ‪.‬‬\n\n\n‫‪365‬‬\n\f‫احلمــد هلل وحــده وبعــد و يف هــذا اليــوم األحــد املوافــق ‪1434/07/30‬ه ـ‬\n‫الســاعة التاســعة افتتحــت اجللســة وســألت املدعــى عليــه عــن الشــهود‬\n‫فأجــاب الشــاهد األول والثانــي بينــي وبينهمــا عــداوة يف العمــل فقــط‬\n‫وليــس لــدي بينــة علــى ذلــك هكــذا أجــاب ثــم طلبــت مــن املدعــى تعديــل‬\n‫ال مــن ‪ ....‬ســعودي بالســجل املدنــي رقــم ‪ .....‬و‪.....‬‬‫بينتــه فأحضــر ك ً‬\n‫ســعودي بالســجل املدنــي رقــم‪ .....‬اللذيــن شــهدا بعدالــة الشــاهدين‬\n‫وأضافــا أنهمــا مرضيــان يف دينهمــا ومرؤتهمــا وال نعلــم عنهمــا إال كل‬\n‫خيــر وحيــث أن الشــهود الذيــن أحضرهــم املدعــي شــهد أحدهــم أن‬\n‫املدعــى عليــه تلفــظ بكلمــة يــا خنيــث وأمــا الشــاهد اآلخــر فلــم يشــهد‬\n‫بهــا لــذا فقــد أفهمــت املدعــي أن البينــة التــي أحضرهــا ناقصــة والبــد‬\n‫مــن إحضــار شــاهد آخــر يشــهد أن املدعــى عليــه قــال لــه يــا خنيــث أو‬\n‫ا إننــي لــن أحضــر‬  ‫يحلــف اليمــن مــع الشــاهد الــذي شــهد فأجــاب قائـ ً‬\n‫شــاهد آخــر ولــن أحلــف اليمــن علــى الرغــم أننــي صــادق يف دعــواي‬\n‫ولكــن ال أريــد أن يثبــت عليــه حــد القــذف ويترتــب عليــه آثــار احلــد‬\n‫وأكتفــي بالبينــة التــي أحضرتهــا وأطلــب تعزيــره فقــط وبعــد ســماع‬\n‫الدعــوى واإلجابــة وحيــث أحضــر املدعــي شــاهدين شــهد أحدهمــا‬\n‫مبوجــب حــد القــذف ولــم يشــهد اآلخــر لــذا فقــد صرفــت النظــر عــن‬\n‫طلــب املدعــي إقامــة حــد القــذف علــى املدعــى عليــه وثبــت لــدي بالبينــة‬\n‫املعدلــة قيــام املدعــى عليــه بســب املدعــي والتلفــظ عليــه بألفــاظ نابيــة‬\n‫وألن املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه لــذا فقــد قــرت‬\n‫تعزيــر املدعــى عليــه بجلــده خمســن جلــده تنفــذ عليــه دفعــة واحــدة‬\n‫ويف مــكان عــام مــع أخــذ التعهــد عليــه بحفــظ لســانه وهــذا اجللــد حــق‬\n‫خــاص للمدعــي ميكــن مــن حضــوره إن رغــب ذلــك وإن عفــا عنــه فهــو‬\n\n\n                                                                                    ‫‪366‬‬\n\f      ‫حــق لــه هــذا مــا ظهــر لــي وبــه حكمــت وبعرضــه عليهمــا قــرر املدعــي‬\n      ‫القناعــة وأمــا املدعــى عليــه فقــد قــرر عــدم القناعــة وطلــب االســتئناف‬\n      ‫بالئحــة اعتراضيــة ومت إفهامــه بالتعليمــات وأن لــه مــدة ثالثــن يومـ ًا مــن‬\n      ‫تاريــخ اســتالم الصــك لتقــدمي الئحتــه االعتراضيــة وإذا مضــت هــذه املــدة‬\n      ‫ولــم يقــدم اعتراضــه فــإن حقــه يف طلــب االســتئناف يســقط ويكتســب‬\n      ‫احلكــم الصفــة القطعيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                            ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/07/30‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ثــم جــرى رفــع املعاملــة حملكمــة االســتئناف‬\n      ‫بالقصيــم فعــادت مصادقـ ًا عليهــا مبوجــب قــرار أصحــاب الفضيلــة رقــم‬\n      ‫‪ 34323110‬يف ‪ 1434/9/21‬ه ـ وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                                                         ‫نبينــا محمــد ‪.‬‬\n\n\n\n\n‫‪367‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":363,"source_page_end":367,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"89589b26e27e0c5302bb4f7a0289cc9e24643e26cb1ac16bba8aba7e856a3e51","normalized_text_hash":"be324f155bb73699d8d3be715d6688f947c205a6a8f004da37ec5686537aae50","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p363-34283087"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
